 lines+=['',f"Primary−Global6: v{pair['v']['mean']:+.4f}pp CI{pair['v']['CI95']}, t{pair['t']['mean']:+.4f}pp CI{pair['t']['CI95']}. Primary−Source: v{source['v']['mean']:+.4f}pp, t{source['t']['mean']:+.4f}pp.",f"Primary−conditional self-hull: v{control['v']['mean']:+.4f}pp CI{control['v']['CI95']}, t{control['t']['mean']:+.4f}pp CI{control['t']['CI95']}.",f"Primary shortt{g['short_le5s']['ConditionalClause']['t']:+.4f}pp,longt{g['long_gt5s']['ConditionalClause']['t']:+.4f}pp vsG6; vsSource short{sg['short_le5s']['ConditionalClause']:+.4f},long{sg['long_gt5s']['ConditionalClause']:+.4f}pp."]
 passed=pair['v']['mean']>0 and pair['t']['mean']>0 and source['v']['mean']>0 and source['t']['mean']>0 and pair['t']['improved']>pair['t']['harmed'] and all(sg[x]['ConditionalClause']>0 for x in sg)and control['t']['mean']>0
 lines+=['','Basic development screen passes only; fixed dual-domain recheck required.'if passed else'Not qualified for main/full promotion. No duration bin/conditional strength sweep.',f"All native posterior aliases/Source/spatial boxes bitwise64; native-target conditional no-op exact64. Maximum grid-span mass error{maxerr:.3g}; maximum within-span physical-duration spread{spread}frames. Official/dense checks{r['checks']} maxerror{r['max_metric_error']:.3g}. CPU cache worker{s['seconds']:.2f}s; zero new model/encoder/text/expert/observation/optimizer. Not end-to-end deployment time, which includes native clause reads.",'','[Signed](signed.tsv), [severe tails](severe_declines.tsv), [Source duration groups](source_duration_groups.json), [information audit](information_audit.json), [protocol](protocol.json).']
